N['WL_exp_min'] = min(N['W_exp6_b'], N['L_exp6_b']); N['WL_exp_max'] = max(N['W_exp6_a'], N['L_exp6_a'])

def fmt(m):
    name, spec = m.group(1), m.group(2)
    if name not in N: raise KeyError('missing value ' + name)
    v = N[name]
    neg = lambda s: s.replace('-', '−')
    if spec == '%': return f"{round(v):d}%"
    if spec == '0': return f"{round(v):d}"
    if spec == 'n': return f"{int(round(v)):,}"
    if spec == '1': return neg(f"{v:.1f}")
    if spec == '2': return neg(f"{v:.2f}")
    if spec == 'a1': return f"{abs(v):.1f}"
    if spec == 's1': return neg(f"{v:+.1f}")
    raise ValueError(spec)

# Korean particles after a number depend on how its last character is read (0 영, 1 일, 2 이, 3 삼, 4 사, 5 오, 6 육, 7 칠,
# 8 팔, 9 구, % 퍼센트): vowel, final ㄹ, or another final consonant.
def ending(txt):
    c = txt[-1]
    if c in '2459%': return 'V'
    if c in '178': return 'L'
    return 'C'
PART = {'이다': ('다', '이다', '이다'), '다': ('다', '이다', '이다'), '으로': ('로', '로', '으로'), '로': ('로', '로', '으로'),
        '이': ('가', '이', '이'), '가': ('가', '이', '이'), '을': ('를', '을', '을'), '를': ('를', '을', '을'),
        '과': ('와', '과', '과'), '와': ('와', '과', '과'), '은': ('는', '은', '은'), '는': ('는', '은', '은')}
def fmt_part(m):
    txt = fmt(m)
    p = m.group(3)
    if not p: return txt
    e = ending(txt)
    return txt + PART[p][0 if e == 'V' else 1 if e == 'L' else 2]

for k, v in S.items():
    T = T.replace('{{' + k + '}}', v)
T = T.replace('ELINSRC', ELINSRC).replace('LINSRC', LINSRC)
class _M:
    def __init__(self, m): self.m = m
    def group(self, i): return self.m.group(i) if i < 3 else (self.m.group(3) or self.m.group(4) or self.m.group(5))
TOKEN = re.compile(r'⟪(\w+)\|(\w+|%)⟫(?:(이다|다)(?=[.,)(\s])|(으로|로)(?=[\s,.)])|(이|가|을|를|과|와|은|는)(?=\s))?')
T = TOKEN.sub(lambda m: fmt_part(_M(m)), T)
left = re.findall(r'\{\{(\w+)\}\}', T) + re.findall(r'⟪[^⟫]*⟫', T)
(ROOT / 'exp/endgame-king/doc.filled.md').write_text(T, encoding='utf8')
print('filled; left placeholders:', left)
